/// One choice of a select, radio group or multi-select: its value and its text.
class CruftFreeOption<T> {
  const CruftFreeOption(this.value, this.label, [this.group, this.description]);

  final T value;
  final String label;

  /// The heading a choice of several keys lists this option under; `null`: none.
  final String? group;

  /// The sentence shown under this option's text (`description:`); `null`: none.
  final String? description;
}

/// The member [path] names, found by walking [row] one wire property at a time; `null` when a
/// step is missing.
Object? _choiceMember(Map<String, Object?> row, List<String> path) {
  Object? current = row;
  for (final step in path) {
    if (current is! Map<String, Object?>) {
      return null;
    }
    current = current[step];
  }
  return current;
}

/// The choices the [rows] of a route offer: each row is one choice, holding the key found along
/// [valuePath] and shown as the text found along [labelPath] (the wire property paths of the
/// member chains the author wrote). A missing text is an empty text; a row without a key offers
/// no choice, as nothing could be picked by it. With [groupPath] a choice is listed under the
/// heading found along it, and with [descriptionPath] it shows the sentence found along that under
/// its text (none for a missing or empty one).
List<CruftFreeOption<T>> cruftfreeChoices<T>(Iterable<Map<String, Object?>> rows, List<String> valuePath, List<String> labelPath, [List<String>? groupPath, List<String>? descriptionPath]) {
  return [
    for (final row in rows)
      if (_choiceMember(row, valuePath) case final T key) CruftFreeOption<T>(key, '${_choiceMember(row, labelPath) ?? ''}', groupPath == null ? null : _choiceOptionalText(row, groupPath), descriptionPath == null ? null : _choiceOptionalText(row, descriptionPath)),
  ];
}

/// The text [row] holds along [path] (a heading, a description); `null` when it has none.
String? _choiceOptionalText(Map<String, Object?> row, List<String> path) {
  final found = _choiceMember(row, path);
  final text = found == null ? '' : '$found';
  return text.isEmpty ? null : text;
}

/// The choices a list of keys offers: each key is its own key and text.
List<CruftFreeOption<T>> cruftfreeKeyChoices<T>(Iterable<T> keys) => [for (final key in keys) CruftFreeOption<T>(key, '$key')];

/// The keys held after the choice keyed [key] is toggled: removed when held, else appended; every
/// other key stays where it is, whether or not its row is on a page shown.
List<T> cruftfreeToggledKeys<T>(List<T> held, T key) => held.contains(key)
    ? [
        for (final one in held)
          if (one != key) one,
      ]
    : [...held, key];

