      if (!choices.any((choice) => choice.value == pick.value)) pick,
  ];
  return missing.isEmpty ? choices : [...choices, ...missing];
}

/// The choices of the keys [held] (a key, or a list of keys) that no row of [shown] has -- their
/// rows are on no page shown -- each found by [lookup], the route answering one row by its key, and
/// read along [valuePath] and [labelPath]. A key whose lookup fails is left out: it shows as the
/// key itself, and never blocks the form that holds it.
Future<List<CruftFreeOption<Object>>> cruftfreeResolveHeld(Object? held, List<CruftFreeOption<Object>> shown, Future<Map<String, Object?>> Function(Object key) lookup, List<String> valuePath, List<String> labelPath) async {
  final found = <CruftFreeOption<Object>>[];
  for (final key in held is List ? held : [held]) {
    if (key == null || key == '' || shown.any((choice) => choice.value == key)) {
      continue;
    }
    try {
      found.addAll(cruftfreeChoices<Object>([await lookup(key)], valuePath, labelPath));
    } on Object {
      continue;
    }
  }
  return found;
}

/// The text of the choice among [choices] holding [key]: the key itself, as text, when no choice
/// holds it.
String cruftfreeChoiceLabel<T>(List<CruftFreeOption<T>> choices, Object? key) {
  for (final choice in choices) {
    if (choice.value == key) {
      return choice.label;
    }
  }
  return '$key';
}

/// The entry of a menu that clears its choice: it holds no value and reads as the framework's
/// clear text.
DropdownMenuEntry<T?> _cruftfreeClearEntry<T>() => DropdownMenuEntry<T?>(value: null, label: cruftfreeRuntime.messages.key('framework.clear').text);

/// `select(label?) : bind(member)?`: one of the options, from a menu. Given [onCleared] (the
/// member is optional), the menu offers to clear the choice, which writes no value.
class CruftFreeSelect<T> extends StatelessWidget {
  const CruftFreeSelect({super.key, this.label, this.value, required this.options, this.onChanged, this.onCleared, this.onChange, this.enabled = true, this.style});

  final String? label;
  final T? value;
  final List<CruftFreeOption<T>> options;
  final ValueChanged<T>? onChanged;

  /// Set when the choice may be cleared: the menu then offers to.
  final VoidCallback? onCleared;
  final VoidCallback? onChange;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final label = this.label;
    final cleared = onCleared;
    final menu = DropdownMenu<T?>(
      key: ValueKey<T?>(value),
      label: label == null ? null : Text(label),
      initialSelection: value,
      enabled: enabled,
      expandedInsets: EdgeInsets.zero,
      dropdownMenuEntries: [
        if (cleared != null) _cruftfreeClearEntry<T>(),
        for (final option in options) DropdownMenuEntry<T?>(value: option.value, label: option.label),
      ],
      onSelected: (selected) {
        if (selected != null) {
          onChanged?.call(selected);
          onChange?.call();
        } else if (cleared != null && value != null) {
          cleared();
          onChange?.call();
        }
      },
    );
    return cruftfreeStyled(context, style, menu);
  }
}

/// The most rows a choice list read whole shows as a plain menu.
const int cruftfreeChoiceComboboxThreshold = 20;

/// How long typing pauses before a live input acts on its text: a choice picker sends it to its
/// route as the search, a table's live filter applies.
const Duration cruftfreeLiveInputDelay = Duration(milliseconds: 300);

/// Whether a choice list of [rows] loaded rows is searched in a picker: always when its route pages,
/// and for a single choice (not [multiple]) whose rows carry descriptions ([described]), which a
/// plain menu cannot show.
bool cruftfreeUsesCombobox(int rows, bool paged, [bool described = false, bool multiple = false]) => paged || rows > cruftfreeChoiceComboboxThreshold || (described && !multiple);

/// Whether a choice list is drawn as cards: when it asks for them and is read whole.
bool cruftfreeShowsCards(bool cards, bool paged) => cards && !paged;

/// Whether any of [choices] carries a description.
bool cruftfreeDescribed<T>(List<CruftFreeOption<T>> choices) => choices.any((choice) => choice.description != null);

/// The width the grid of choice cards aims for: as many columns as fit at this width.
const double cruftfreeCardWidth = 224;

/// The columns of a grid of choice cards in [width]: at least one.
int cruftfreeCardColumns(double width) {
  if (!width.isFinite) {
    return 1;
  }
  final fitting = width ~/ cruftfreeCardWidth;
  return fitting < 1 ? 1 : fitting;
}

/// The choices whose label contains [typed], ignoring surrounding space and letter case.
List<CruftFreeOption<T>> cruftfreeMatchingChoices<T>(List<CruftFreeOption<T>> choices, String typed) {
  final needle = typed.trim().toLowerCase();
  return [
    for (final choice in choices)
      if (choice.label.toLowerCase().contains(needle)) choice,
  ];
}

/// [choices] with [chosen] -- the row picked last -- added when it is on no page among them, so
/// its text is still found.
List<CruftFreeOption<T>> cruftfreeWithChosen<T>(List<CruftFreeOption<T>> choices, CruftFreeOption<T>? chosen) {
  if (chosen == null || choices.any((choice) => choice.value == chosen.value)) {
    return choices;
  }
  return [...choices, chosen];
}

/// The input of a choice list read from the rows of a route (`options(route, value: ..., label:
/// ..., search: q)`), holding the key of the row picked and showing its text.
///
/// A list read whole of at most [cruftfreeChoiceComboboxThreshold] rows is a plain menu. A longer one,
/// and every list read from a paginated route ([pages]), opens a picker: a search field, the
/// matching choices, and for a paginated route previous and next moves through its pages.
/// Without [search] the typed text narrows the choices loaded ([cruftfreeMatchingChoices]); with it,
/// the text is sent to the route as the filter [search] names once typing has paused for
/// [cruftfreeLiveInputDelay], and the route's answer is the list, from its first page. The row
/// picked is kept, so its text shows also when it is on no page shown; a key no row was picked
/// for is shown as itself.
class CruftFreeChoicePicker<T> extends StatefulWidget {
  const CruftFreeChoicePicker({super.key, this.label, this.value, required this.choices, this.known, this.cards = false, this.pages, this.search, this.onChanged, this.onCleared, this.onChange, this.errorText, this.enabled = true, this.style});

  final String? label;
  final T? value;

  /// The choices offered now: every row of a list read whole, or the page of [pages] shown.
  final List<CruftFreeOption<T>> Function() choices;

  /// The row the owner knows for a key it holds whose row is on no page shown (a form that opened
  /// holding values looked it up), so its text shows in place of the key; `null` without.
  final CruftFreeOption<T>? Function()? known;

  /// Whether a list read whole is drawn as one selectable card per choice ([cruftfreeShowsCards]).
  final bool cards;

  /// The paginated route's binding the choices come from; `null` for a list read whole.
  final PagedBinding<Object?>? pages;

  /// The filter of [pages] the typed text is sent as; `null` narrows the loaded choices instead.
  final String? search;

  /// The row picked: its key, and the row itself.
  final void Function(T value, CruftFreeOption<T> choice)? onChanged;

  /// Set when the choice may be cleared: the picker then offers to.
  final VoidCallback? onCleared;
  final VoidCallback? onChange;
  final String? errorText;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeChoicePicker<T>> createState() => _CruftFreeChoicePickerState<T>();
}

class _CruftFreeChoicePickerState<T> extends State<CruftFreeChoicePicker<T>> {
  /// The row picked last: its text shows while it is on no page shown.
  CruftFreeOption<T>? _chosen;

  /// Whether the open dialog sent a search: the route is read unnarrowed again once it closes.
  bool _searched = false;

  List<CruftFreeOption<T>> _offered() => cruftfreeWithChosen(cruftfreeWithChosen(widget.choices(), widget.known?.call()), _chosen);

  void _picked(CruftFreeOption<T> choice) {
    setState(() => _chosen = choice);
    widget.onChanged?.call(choice.value, choice);
    widget.onChange?.call();
  }

  void _cleared() {
    setState(() => _chosen = null);
    widget.onCleared?.call();
    widget.onChange?.call();
  }

  Future<void> _open() async {
    final pages = widget.pages;
    final picked = await showDialog<_CruftFreePick<T>>(
      context: context,
      builder: (context) => _CruftFreeChoiceDialog<T>(title: widget.label, value: widget.value, choices: widget.choices, pages: pages, search: widget.search, onSearched: () => _searched = true, clearable: widget.onCleared != null && widget.value != null),
    );
    if (_searched) {
      _searched = false;
      pages?.setFilters(const {});
    }
    if (!mounted || picked == null) {
      return;
    }
    final choice = picked.choice;
    if (choice == null) {
      _cleared();
    } else {
      _picked(choice);
    }
  }

  @override
  Widget build(BuildContext context) {
    final offered = _offered();
    final label = widget.label;
    if (cruftfreeShowsCards(widget.cards, widget.pages != null)) {
      final cards = _CruftFreeChoiceCards<T>(label: label, choices: offered, multiple: false, enabled: widget.enabled, errorText: widget.errorText, isChosen: (choice) => choice.value == widget.value, onChoose: _picked);
      return cruftfreeStyled(context, widget.style, cards);
    }
    if (!cruftfreeUsesCombobox(offered.length, widget.pages != null, cruftfreeDescribed(offered))) {
      final clearable = widget.onCleared != null;
      final menu = DropdownMenu<T?>(
        key: ValueKey<T?>(widget.value),
        label: label == null ? null : Text(label),
        initialSelection: widget.value,
        enabled: widget.enabled,
        errorText: widget.errorText,
        expandedInsets: EdgeInsets.zero,
        dropdownMenuEntries: [
          if (clearable) _cruftfreeClearEntry<T>(),
          for (final choice in offered) DropdownMenuEntry<T?>(value: choice.value, label: choice.label),
        ],
        onSelected: (selected) {
          if (selected == null) {
            if (clearable && widget.value != null) {
              _cleared();
            }
            return;
          }
          for (final choice in offered) {
            if (choice.value == selected) {
              _picked(choice);
              return;
            }
          }
        },
      );
      return cruftfreeStyled(context, widget.style, menu);
    }
    final value = widget.value;
    final shown = value == null ? '' : cruftfreeChoiceLabel(offered, value);
    final field = Semantics(
      button: true,
      enabled: widget.enabled,
      label: label,
      value: shown,
      excludeSemantics: true,
      child: InkWell(
        onTap: widget.enabled ? _open : null,
        child: InputDecorator(
          decoration: InputDecoration(labelText: label, errorText: widget.errorText, enabled: widget.enabled, suffixIcon: const Icon(Icons.search)),
          isEmpty: shown.isEmpty,
          child: Text(shown),
        ),
      ),
    );
    return cruftfreeStyled(context, widget.style, field);
  }
}

/// What the picker's dialog answers: the row picked, or `null` for a cleared choice.
class _CruftFreePick<T> {
  const _CruftFreePick(this.choice);

  final CruftFreeOption<T>? choice;
}

class _CruftFreeChoiceDialog<T> extends StatefulWidget {
  const _CruftFreeChoiceDialog({required this.title, required this.value, required this.choices, required this.pages, required this.search, required this.onSearched, required this.clearable});

  final String? title;
  final T? value;
  final List<CruftFreeOption<T>> Function() choices;
  final PagedBinding<Object?>? pages;
  final String? search;
  final VoidCallback onSearched;
  final bool clearable;

  @override
  State<_CruftFreeChoiceDialog<T>> createState() => _CruftFreeChoiceDialogState<T>();
}

class _CruftFreeChoiceDialogState<T> extends State<_CruftFreeChoiceDialog<T>> {
  String _typed = '';
  Timer? _searchTimer;

  @override
  void dispose() {
    _searchTimer?.cancel();
    super.dispose();
  }

  void _type(String text) {
    setState(() => _typed = text);
    final pages = widget.pages;
    final search = widget.search;
    if (pages == null || search == null) {
      return;
    }
    _searchTimer?.cancel();
    _searchTimer = Timer(cruftfreeLiveInputDelay, () {
      final narrowed = text.trim();
      widget.onSearched();
      pages.setFilters(narrowed.isEmpty ? const {} : {search: narrowed});
    });
  }

  String _text(String key) => cruftfreeRuntime.messages.key(key).text;

  Widget _list(BuildContext context) {
    final pages = widget.pages;
    final choices = widget.search == null ? cruftfreeMatchingChoices(widget.choices(), _typed) : widget.choices();
    // A request of the pages that failed and left no choice shows its problem and a retry, never
    // the empty-result text; a failed refresh keeps the choices it had.
    final failure = pages?.error;
    if (pages != null && failure != null && !pages.isLoading && choices.isEmpty) {
      return CruftFreeErrorState(failure: failure, onRetry: pages.refresh);
    }
    final list = choices.isEmpty
        ? Padding(padding: EdgeInsets.all(CruftFreeTokens.of(context).inset), child: Text(_text(pages != null && pages.isLoading ? 'framework.loading' : 'framework.noMatches')))
        : ListView(
            shrinkWrap: true,
            children: [for (final choice in choices) ListTile(title: Text(choice.label), subtitle: choice.description == null ? null : Text(choice.description!), selected: choice.value == widget.value, onTap: () => Navigator.of(context).pop(_CruftFreePick<T>(choice)))],
          );
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Flexible(child: list),
        if (pages != null)
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              TextButton(onPressed: pages.hasPrevious ? pages.previous : null, child: Text(_text('framework.previous'))),
              TextButton(onPressed: pages.hasNext ? pages.next : null, child: Text(_text('framework.next'))),
            ],
          ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final title = widget.title;
    final pages = widget.pages;
    return AlertDialog(
      title: title == null ? null : Text(title),
      content: SizedBox(
        width: double.maxFinite,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            TextField(
              autofocus: true,
              decoration: InputDecoration(labelText: _text('framework.search'), prefixIcon: const Icon(Icons.search)),
              onChanged: _type,
            ),
            Flexible(
              child: pages == null ? _list(context) : ListenableBuilder(listenable: pages, builder: (context, _) => _list(context)),
            ),
          ],
        ),
      ),
      actions: [
        if (widget.clearable) TextButton(onPressed: () => Navigator.of(context).pop(_CruftFreePick<T>(null)), child: Text(_text('framework.clear'))),
        TextButton(onPressed: () => Navigator.of(context).pop(), child: Text(_text('framework.cancel'))),
      ],
    );
  }
}

/// The input of a choice of several keys (`multiSelect(label?) : bind(member), options(source, ...)`),
/// holding the keys picked in the order they were picked and showing the text of their rows.
///
/// The threshold of [CruftFreeChoicePicker] decides its shape: a list read whole of at most
/// [cruftfreeChoiceComboboxThreshold] rows is a group of checkboxes, a longer one and every list read
/// from a paginated route ([pages]) a field opening a dialog of checkboxes, with the keys held
/// shown as removable chips. A pick toggles its key ([cruftfreeToggledKeys]) and leaves every other key
/// held, whether or not its row is on a page shown. Choices under a heading ([CruftFreeOption.group])
/// are listed under it ([cruftfreeGroupedChoices]).
class CruftFreeMultiChoicePicker<T> extends StatefulWidget {
  const CruftFreeMultiChoicePicker({super.key, this.label, required this.values, required this.choices, this.known, this.cards = false, this.pages, this.search, this.onChanged, this.onPicked, this.onChange, this.errorText, this.enabled = true, this.style});

  final String? label;

  /// The keys held now, in the order they were picked.
  final List<T> values;

  /// The choices offered now: every row of a list read whole, or the page of [pages] shown.
  final List<CruftFreeOption<T>> Function() choices;

  /// The rows the owner knows for keys it holds whose rows are on no page shown (a form that opened
  /// holding values looked them up), so their text shows in place of the keys; `null` without.
  final List<CruftFreeOption<T>> Function()? known;

  /// Whether a list read whole is drawn as one selectable card per choice ([cruftfreeShowsCards]).
  final bool cards;

  /// The paginated route's binding the choices come from; `null` for a list read whole.
  final PagedBinding<Object?>? pages;

  /// The filter of [pages] the typed text is sent as; `null` narrows the loaded choices instead.
  final String? search;

  /// The keys held after a pick or a removal: a new list.
  final ValueChanged<List<T>>? onChanged;

  /// Every row picked so far: a review shows their text.
  final ValueChanged<List<CruftFreeOption<T>>>? onPicked;
  final VoidCallback? onChange;
  final String? errorText;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeMultiChoicePicker<T>> createState() => _CruftFreeMultiChoicePickerState<T>();
}

class _CruftFreeMultiChoicePickerState<T> extends State<CruftFreeMultiChoicePicker<T>> {
  /// Every row picked: its text shows while it is on no page shown.
  List<CruftFreeOption<T>> _chosen = const [];
  late List<T> _held = widget.values;
  bool _searched = false;

  @override
  void didUpdateWidget(CruftFreeMultiChoicePicker<T> oldWidget) {
    super.didUpdateWidget(oldWidget);
    _held = widget.values;
  }

  List<CruftFreeOption<T>> _offered() => cruftfreeWithChosenRows(cruftfreeWithChosenRows(widget.choices(), widget.known?.call() ?? const []), _chosen);

  void _settle(List<T> keys) {
    setState(() => _held = keys);
    widget.onChanged?.call(keys);
    widget.onPicked?.call(_chosen);
    widget.onChange?.call();
  }

  void _toggle(CruftFreeOption<T> choice) {
    if (!_chosen.any((row) => row.value == choice.value)) {
      _chosen = [..._chosen, choice];
    }
    _settle(cruftfreeToggledKeys(_held, choice.value));
  }

  Future<void> _open() async {
    final pages = widget.pages;
    await showDialog<void>(
      context: context,
      builder: (context) => _CruftFreeMultiChoiceDialog<T>(title: widget.label, held: () => _held, choices: widget.choices, pages: pages, search: widget.search, onSearched: () => _searched = true, onToggle: _toggle),
    );
    if (_searched) {
      _searched = false;
      pages?.setFilters(const {});
    }
  }

  List<Widget> _sections(BuildContext context, List<CruftFreeOption<T>> offered) {
    final theme = Theme.of(context);
    return [
      for (final section in cruftfreeGroupedChoices(offered)) ...[
        if (section.heading != null)
          Padding(
            padding: EdgeInsets.only(top: CruftFreeTokens.of(context).inset / 2),
            child: ExcludeSemantics(child: Text(section.heading!, style: theme.textTheme.labelLarge)),
          ),
        for (final choice in section.choices) CheckboxListTile(key: ValueKey<T>(choice.value), value: _held.contains(choice.value), title: Text(choice.label), subtitle: choice.description == null ? null : Text(choice.description!), dense: true, controlAffinity: ListTileControlAffinity.leading, onChanged: widget.enabled ? (_) => _toggle(choice) : null),
      ],
    ];
  }

  @override
  Widget build(BuildContext context) {
    final offered = _offered();
    final label = widget.label;
    final error = widget.errorText;
    final Widget body;
    if (cruftfreeShowsCards(widget.cards, widget.pages != null)) {
      body = _CruftFreeChoiceCards<T>(label: label, choices: offered, multiple: true, enabled: widget.enabled, errorText: error, isChosen: (choice) => _held.contains(choice.value), onChoose: _toggle);
    } else if (!cruftfreeUsesCombobox(offered.length, widget.pages != null, false, true)) {
      body = Semantics(
        container: true,
        label: label,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (label != null) Text(label, style: Theme.of(context).textTheme.bodyLarge),
            if (offered.isEmpty) Text(cruftfreeRuntime.messages.key('framework.noMatches').text),
            ..._sections(context, offered),
            if (error != null) Text(error, style: TextStyle(color: Theme.of(context).colorScheme.error)),
          ],
        ),
      );
    } else {
      final shown = [for (final key in _held) cruftfreeChoiceLabel(offered, key)];
      body = Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (shown.isNotEmpty)
            Wrap(
              spacing: CruftFreeTokens.of(context).inset / 2,
              children: [for (var index = 0; index < shown.length; index++) InputChip(label: Text(shown[index]), deleteButtonTooltipMessage: '${cruftfreeRuntime.messages.key('framework.remove').text} ${shown[index]}', onDeleted: widget.enabled ? () => _settle(cruftfreeToggledKeys(_held, _held[index])) : null)],
            ),
          Semantics(
            button: true,
            enabled: widget.enabled,
            label: label,
            excludeSemantics: true,
            child: InkWell(
              onTap: widget.enabled ? _open : null,
              child: InputDecorator(
                decoration: InputDecoration(labelText: label, errorText: error, enabled: widget.enabled, suffixIcon: const Icon(Icons.search)),
                isEmpty: true,
                child: const SizedBox(width: double.infinity),
              ),
            ),
          ),
        ],
      );
    }
    return cruftfreeStyled(context, widget.style, body);
  }
}

class _CruftFreeMultiChoiceDialog<T> extends StatefulWidget {
  const _CruftFreeMultiChoiceDialog({required this.title, required this.held, required this.choices, required this.pages, required this.search, required this.onSearched, required this.onToggle});

  final String? title;
  final List<T> Function() held;
  final List<CruftFreeOption<T>> Function() choices;
  final PagedBinding<Object?>? pages;
  final String? search;
  final VoidCallback onSearched;
  final void Function(CruftFreeOption<T> choice) onToggle;

  @override
  State<_CruftFreeMultiChoiceDialog<T>> createState() => _CruftFreeMultiChoiceDialogState<T>();
}

class _CruftFreeMultiChoiceDialogState<T> extends State<_CruftFreeMultiChoiceDialog<T>> {
  String _typed = '';
  Timer? _searchTimer;

  @override
  void dispose() {
    _searchTimer?.cancel();
    super.dispose();
  }

  void _type(String text) {
    setState(() => _typed = text);
    final pages = widget.pages;
    final search = widget.search;
    if (pages == null || search == null) {
      return;
    }
    _searchTimer?.cancel();
    _searchTimer = Timer(cruftfreeLiveInputDelay, () {
      final narrowed = text.trim();
      widget.onSearched();
      pages.setFilters(narrowed.isEmpty ? const {} : {search: narrowed});
    });
  }

  String _text(String key) => cruftfreeRuntime.messages.key(key).text;

  Widget _list(BuildContext context) {
    final pages = widget.pages;
    final choices = widget.search == null ? cruftfreeMatchingChoices(widget.choices(), _typed) : widget.choices();
    final held = widget.held();
    final list = choices.isEmpty
        ? Padding(padding: EdgeInsets.all(CruftFreeTokens.of(context).inset), child: Text(_text(pages != null && pages.isLoading ? 'framework.loading' : 'framework.noMatches')))
        : ListView(
