    final pages = widget.pages;
    return AlertDialog(
      title: title == null ? null : Text(title),
      content: SizedBox(
        width: double.maxFinite,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            TextField(
              autofocus: true,
              decoration: InputDecoration(labelText: _text('framework.search'), prefixIcon: const Icon(Icons.search)),
              onChanged: _type,
            ),
            Flexible(
              child: pages == null ? _list(context) : ListenableBuilder(listenable: pages, builder: (context, _) => _list(context)),
            ),
          ],
        ),
      ),
      actions: [TextButton(onPressed: () => Navigator.of(context).pop(), child: Text(_text('framework.confirm')))],
    );
  }
}

/// A choice list drawn as cards (`cards`): one selectable card per choice -- its text and its
/// description -- in a grid of as many columns as fit ([cruftfreeCardColumns]), under the headings the
/// choices are listed under ([cruftfreeGroupedChoices]). Each card is announced as a checkbox
/// ([multiple]) or as one of a group of radio buttons, checked when chosen, with the description
/// as its hint; it takes a tap, or Enter or Space once focused. What is chosen shows as a
/// checked mark and a heavier border, not only as a colour.
class _CruftFreeChoiceCards<T> extends StatelessWidget {
  const _CruftFreeChoiceCards({required this.label, required this.choices, required this.multiple, required this.enabled, required this.errorText, required this.isChosen, required this.onChoose});

  final String? label;
  final List<CruftFreeOption<T>> choices;
  final bool multiple;
  final bool enabled;
  final String? errorText;
  final bool Function(CruftFreeOption<T> choice) isChosen;
  final void Function(CruftFreeOption<T> choice) onChoose;

  Widget _card(BuildContext context, CruftFreeOption<T> choice) {
    final theme = Theme.of(context);
    final inset = CruftFreeTokens.of(context).inset;
    final chosen = isChosen(choice);
    final description = choice.description;
    final shape = RoundedRectangleBorder(
      borderRadius: BorderRadius.circular(inset / 2),
      side: BorderSide(color: chosen ? theme.colorScheme.primary : theme.dividerColor, width: chosen ? 2 : 1),
    );
    final mark = multiple ? (chosen ? Icons.check_box : Icons.check_box_outline_blank) : (chosen ? Icons.radio_button_checked : Icons.radio_button_unchecked);
    void choose() => onChoose(choice);
    return Semantics(
      checked: chosen,
      inMutuallyExclusiveGroup: !multiple,
      enabled: enabled,
      label: choice.label,
      hint: description,
      onTap: enabled ? choose : null,
      excludeSemantics: true,
      child: Card(
        margin: EdgeInsets.zero,
        shape: shape,
        color: chosen ? theme.colorScheme.primaryContainer : theme.colorScheme.surface,
        child: InkWell(
          customBorder: shape,
          onTap: enabled ? choose : null,
          child: Padding(
            padding: EdgeInsets.all(inset),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(mark, color: chosen ? theme.colorScheme.primary : null),
                SizedBox(width: inset / 2),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(choice.label, style: theme.textTheme.titleSmall),
                      if (description != null) Text(description, style: theme.textTheme.bodySmall),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _grid(BuildContext context, List<CruftFreeOption<T>> section) {
    final spacing = CruftFreeTokens.of(context).inset / 2;
    return LayoutBuilder(
      builder: (context, box) {
        final columns = cruftfreeCardColumns(box.maxWidth);
        final width = box.maxWidth.isFinite ? (box.maxWidth - spacing * (columns - 1)) / columns : null;
        return Wrap(
          spacing: spacing,
          runSpacing: spacing,
          children: [for (final choice in section) SizedBox(width: width, child: _card(context, choice))],
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final label = this.label;
    final error = errorText;
    final theme = Theme.of(context);
    final inset = CruftFreeTokens.of(context).inset;
    return Semantics(
      container: true,
      label: label,
      explicitChildNodes: true,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (label != null) ExcludeSemantics(child: Text(label, style: theme.textTheme.bodyLarge)),
          if (choices.isEmpty) Text(cruftfreeRuntime.messages.key('framework.noMatches').text),
          for (final section in cruftfreeGroupedChoices(choices)) ...[
            if (section.heading != null)
              Padding(
                padding: EdgeInsets.only(top: inset / 2, bottom: inset / 2),
                child: ExcludeSemantics(child: Text(section.heading!, style: theme.textTheme.labelLarge)),
              ),
            _grid(context, section.choices),
          ],
          if (error != null) Text(error, style: TextStyle(color: theme.colorScheme.error)),
        ],
      ),
    );
  }
}

/// A group of choices announced under its label. While it is not [enabled] its choices take
/// neither pointer nor keyboard activation and the group is announced as unavailable.
class _ChoiceGroup extends StatelessWidget {
  const _ChoiceGroup({required this.label, required this.children, this.enabled = true});

  final String? label;
  final List<Widget> children;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    final label = this.label;
    final group = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (label != null) ExcludeSemantics(child: Text(label, style: Theme.of(context).textTheme.labelLarge)),
        ...children,
      ],
    );
    return Semantics(
      container: true,
      label: label,
      enabled: enabled ? null : false,
      explicitChildNodes: true,
      child: enabled
          ? group
          : Opacity(
              opacity: 0.38,
              child: IgnorePointer(child: ExcludeFocus(child: group)),
            ),
    );
  }
}

/// `radio(label?) : bind(member)?`: one of the options, each shown.
class CruftFreeRadioGroup<T> extends StatefulWidget {
  const CruftFreeRadioGroup({super.key, this.label, this.value, required this.options, this.onChanged, this.onChange, this.enabled = true, this.style});

  final String? label;
  final T? value;
  final List<CruftFreeOption<T>> options;
  final ValueChanged<T>? onChanged;
  final VoidCallback? onChange;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeRadioGroup<T>> createState() => _CruftFreeRadioGroupState<T>();
}

class _CruftFreeRadioGroupState<T> extends State<CruftFreeRadioGroup<T>> {
  late T? _selected = widget.value;

  @override
  void didUpdateWidget(CruftFreeRadioGroup<T> oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.value != null) {
      _selected = widget.value;
    }
  }

  void _changed(T? selected) {
    if (selected == null) {
      return;
    }
    setState(() => _selected = selected);
    widget.onChanged?.call(selected);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final group = RadioGroup<T>(
      groupValue: _selected,
      onChanged: _changed,
      child: _ChoiceGroup(
        label: widget.label,
        enabled: widget.enabled,
        children: [for (final option in widget.options) RadioListTile<T>(value: option.value, title: Text(option.label))],
      ),
    );
    return cruftfreeStyled(context, widget.style, group);
  }
}

/// `multiSelect(label?) : bind(member)?`: any of the options, each a checkbox.
class CruftFreeMultiSelect<T> extends StatefulWidget {
  const CruftFreeMultiSelect({super.key, this.label, this.values, required this.options, this.onChanged, this.onChange, this.enabled = true, this.style});

  final String? label;
  final Iterable<T>? values;
  final List<CruftFreeOption<T>> options;
  final ValueChanged<List<T>>? onChanged;
  final VoidCallback? onChange;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeMultiSelect<T>> createState() => _CruftFreeMultiSelectState<T>();
}

class _CruftFreeMultiSelectState<T> extends State<CruftFreeMultiSelect<T>> {
  late Set<T> _chosen = {...?widget.values};

  @override
  void didUpdateWidget(CruftFreeMultiSelect<T> oldWidget) {
    super.didUpdateWidget(oldWidget);
    final values = widget.values;
    if (values != null) {
      _chosen = {...values};
    }
  }

  void _changed(T value, bool? checked) {
    setState(() => checked == true ? _chosen.add(value) : _chosen.remove(value));
    widget.onChanged?.call([
      for (final option in widget.options)
        if (_chosen.contains(option.value)) option.value,
    ]);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final group = _ChoiceGroup(
      label: widget.label,
      enabled: widget.enabled,
      children: [for (final option in widget.options) CheckboxListTile(title: Text(option.label), value: _chosen.contains(option.value), onChanged: widget.enabled ? (checked) => _changed(option.value, checked) : null, controlAffinity: ListTileControlAffinity.leading)],
    );
    return cruftfreeStyled(context, widget.style, group);
  }
}

/// Which temporal value a temporal input picks.
enum CruftFreeTemporalKind { date, time, dateTime }

String _pad(int value, int width) => value.toString().padLeft(width, '0');

/// A date-only wire value as a calendar day in the user's own time zone.
DateTime cruftfreeCalendarDate(String value) {
  final parts = value.split('-');
  if (parts.length == 3 && value.length == 10) {
    return DateTime(int.parse(parts[0]), int.parse(parts[1]), int.parse(parts[2]));
  }
  return DateTime.parse(value).toLocal();
}

/// `date`/`time`/`dateTime(label?) : bind(member)?`: the value in the
/// session locale's format, changed through the platform's pickers.
class CruftFreeTemporalInput extends StatefulWidget {
  const CruftFreeTemporalInput({super.key, required this.kind, this.label, this.value, this.onChanged, this.onChange, this.enabled = true, this.style});

  final CruftFreeTemporalKind kind;
  final String? label;
  final String? value;
  final ValueChanged<String>? onChanged;
  final VoidCallback? onChange;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeTemporalInput> createState() => _CruftFreeTemporalInputState();
}

class _CruftFreeTemporalInputState extends State<CruftFreeTemporalInput> {
  late String? _value = widget.value;

  @override
  void didUpdateWidget(CruftFreeTemporalInput oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.value != null) {
      _value = widget.value;
    }
  }

  DateTime _current() {
    final value = _value;
    if (value == null || value.isEmpty) {
      return DateTime.now();
    }
    if (widget.kind == CruftFreeTemporalKind.time) {
      final parts = value.split(':');
      final now = DateTime.now();
      return DateTime(now.year, now.month, now.day, int.parse(parts[0]), int.parse(parts[1]));
    }
    return cruftfreeCalendarDate(value);
  }

  String _shown() {
    final value = _value;
    if (value == null || value.isEmpty) {
      return '';
    }
    final locale = cruftfreeRuntime.session.locale;
    final current = _current();
    return switch (widget.kind) {
      CruftFreeTemporalKind.date => formatDate(current, locale),
      CruftFreeTemporalKind.time => formatTime(current, locale),
      CruftFreeTemporalKind.dateTime => '${formatDate(current, locale)} ${formatTime(current, locale)}',
    };
  }

  Future<DateTime?> _pickDate(DateTime current) {
    return showDatePicker(context: context, initialDate: current, firstDate: DateTime(current.year - 100), lastDate: DateTime(current.year + 100));
  }

  Future<void> _pick() async {
    final current = _current();
    final date = widget.kind == CruftFreeTemporalKind.time ? current : await _pickDate(current);
    if (date == null || !mounted) {
      return;
    }
    if (widget.kind == CruftFreeTemporalKind.date) {
      return _write('${_pad(date.year, 4)}-${_pad(date.month, 2)}-${_pad(date.day, 2)}');
    }
    final time = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(current));
    if (time == null || !mounted) {
      return;
    }
    if (widget.kind == CruftFreeTemporalKind.time) {
      return _write('${_pad(time.hour, 2)}:${_pad(time.minute, 2)}:00');
    }
    _write(DateTime(date.year, date.month, date.day, time.hour, time.minute).toUtc().toIso8601String());
  }

  void _write(String value) {
    setState(() => _value = value);
    widget.onChanged?.call(value);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final icon = widget.kind == CruftFreeTemporalKind.time ? Icons.schedule : Icons.calendar_today;
    final field = InkWell(
      onTap: widget.enabled ? _pick : null,
      child: InputDecorator(
        decoration: InputDecoration(labelText: widget.label, suffixIcon: Icon(icon), enabled: widget.enabled),
        child: Text(_shown()),
      ),
    );
    return cruftfreeStyled(context, widget.style, Semantics(button: true, enabled: widget.enabled ? null : false, child: field));
  }
}

/// `slider(label?) : bind(member)?`: a value from 0 to 100 in whole steps.
class CruftFreeSlider extends StatefulWidget {
  const CruftFreeSlider({super.key, this.label, this.value, this.onChanged, this.onChange, this.enabled = true, this.style});

  final String? label;
  final num? value;
  final ValueChanged<double>? onChanged;
  final VoidCallback? onChange;
  final bool enabled;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeSlider> createState() => _CruftFreeSliderState();
}

class _CruftFreeSliderState extends State<CruftFreeSlider> {
  late double _value = (widget.value ?? _sliderMin).toDouble().clamp(_sliderMin, _sliderMax);

  @override
  void didUpdateWidget(CruftFreeSlider oldWidget) {
    super.didUpdateWidget(oldWidget);
    final value = widget.value;
    if (value != null) {
      _value = value.toDouble().clamp(_sliderMin, _sliderMax);
    }
  }

  void _changed(double value) {
    setState(() => _value = value);
    widget.onChanged?.call(value);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final label = widget.label;
    final slider = Slider(value: _value, min: _sliderMin, max: _sliderMax, divisions: _sliderSteps, label: '${_value.round()}', onChanged: widget.enabled ? _changed : null);
    final labelled = label == null
        ? slider
        : Semantics(
            label: label,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                ExcludeSemantics(child: Text(label)),
                slider,
              ],
            ),
          );
    return cruftfreeStyled(context, widget.style, labelled);
  }
}

/// `fileUpload(label?) : bind(member)?, preview?`: a file chosen from the device; with [preview],
/// the file chosen is shown under the field (`CruftFreeUploadPreview`) and nothing is sent before submit.
class CruftFreeFileUpload extends StatefulWidget {
  const CruftFreeFileUpload({super.key, this.label, this.value, this.onChanged, this.onChange, this.enabled = true, this.preview = false, this.style});

  final String? label;
  final UploadFile? value;
  final ValueChanged<UploadFile>? onChanged;
  final VoidCallback? onChange;
  final bool enabled;
  final bool preview;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeFileUpload> createState() => _CruftFreeFileUploadState();
}

class _CruftFreeFileUploadState extends State<CruftFreeFileUpload> {
  late UploadFile? _chosen = widget.value;

  @override
  void didUpdateWidget(CruftFreeFileUpload oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A bound member the view empties empties the field (and its preview); an unbound field keeps its own choice.
    if (widget.value != null || (widget.onChanged != null && oldWidget.value != null)) {
      _chosen = widget.value;
    }
  }

  Future<void> _choose() async {
    final file = await cruftfreeRuntime.media.pickFile(null);
    if (file == null || !mounted) {
      return;
    }
    setState(() => _chosen = file);
    widget.onChanged?.call(file);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final chosen = _chosen;
    final field = InputDecorator(
      decoration: InputDecoration(labelText: widget.label, enabled: widget.enabled),
      child: Row(
        children: [
          Expanded(child: Text(chosen == null ? '' : chosen.filename)),
          TextButton(onPressed: widget.enabled ? _choose : null, child: Text(cruftfreeRuntime.messages.key('framework.add').text)),
        ],
      ),
    );
    if (!widget.preview || chosen == null) {
      return cruftfreeStyled(context, widget.style, field);
    }
    return cruftfreeStyled(
      context,
      widget.style,
      Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          field,
          CruftFreeUploadPreview(file: chosen),
        ],
      ),
    );
  }
}
